export const MANAGED_BEGIN = "<!-- BEGIN @hunpeolabs/ai-agent-kit managed -->";
export const MANAGED_END = "<!-- END @hunpeolabs/ai-agent-kit managed -->";
export const GENERATED_HEADER = "<!-- Generated by @hunpeolabs/ai-agent-kit. Re-run bootstrap to update. -->";

export function managedSection(body) {
  return `${MANAGED_BEGIN}\n${body.trim()}\n${MANAGED_END}\n`;
}

export function rootInstructions(productName) {
  return managedSection(`
## AI Agent Operating System

This repository uses \`@hunpeolabs/ai-agent-kit\` for local Claude Code and Codex setup.

- Run repository intelligence before planning, review, QA, documentation analysis, or implementation.
- Use CodeGraph for structural impact and CocoIndex for semantic/code/document retrieval.
- Do not edit protected application files before a reviewed plan and explicit human approval.
- Complete quality gates and report memory candidates under shared `.ai/` policy before handoff.
- Keep all bootstrap work local. Developers manually review, stage, commit, push, create MRs, and update Jira.

Shared policy lives under \`.ai/\`. ${productName} adapters live under \`.claude/\` and \`.agents/\`.
`);
}

export function gitignoreSection() {
  return managedSection(`
.codegraph/
.cocoindex_code/
.ai-agent-kit/backups/
.ai-agent-kit/transactions/
`);
}

export function renderCanonicalFiles({ packageVersion, detection, includeClaude, includeCodex }) {
  const files = new Map();
  files.set(".ai/README.md", `${GENERATED_HEADER}
# AI Agent Operating System

This directory is generated and safely maintained by \`@hunpeolabs/ai-agent-kit\`.

Profile: \`${detection.profile}\`
Package version: \`${packageVersion}\`

All repository tasks must run the Repository Intelligence Gate before brainstorming, planning, impact analysis, review, QA analysis, documentation analysis, or implementation.
`);

  files.set(".ai/core/required-workflow.md", `${GENERATED_HEADER}
# Required Workflow

1. Run the Repository Intelligence Gate.
2. Query CodeGraph for structural location, dependencies, callers/callees, and impact.
3. Query CocoIndex for semantic matches, requirements, specs, docs, tests, ADRs, and runbooks.
4. Verify critical conclusions against source code.
5. Produce indexed facts, source-code verified facts, assumptions, unknowns, alternatives, smallest safe solution, regression risks, and recommended direction.
6. For existing-system changes, stop after a detailed plan until explicit human approval exists.
7. After approved implementation, compare actual diff to approved scope, refresh indexes, and re-run validation.
`);

  files.set(".ai/guards/repository-intelligence-gate.yaml", `${GENERATED_HEADER}
version: 1
name: repository-intelligence-gate
mode: fail-closed
tools:
  codegraph:
    package: "@colbymchenry/codegraph@1.5.0"
    executable: "codegraph"
    role: "structural graph and impact analysis"
  cocoindex:
    package: "cocoindex-code[full]==0.2.39"
    executable: "ccc"
    role: "semantic code and documentation retrieval"
required_before:
  - brainstorming
  - planning
  - impact-analysis
  - code-review
  - qa-analysis
  - documentation-analysis
  - implementation
exclude:
  - ".git/**"
  - ".codegraph/**"
  - ".cocoindex_code/**"
  - "node_modules/**"
  - "target/**"
  - "build/**"
  - "dist/**"
  - "coverage/**"
  - "**/*.log"
  - "**/.env"
  - "**/.env.*"
  - "**/secrets/**"
  - "**/*.pem"
  - "**/*token*"
  - "**/*private-key*"
  - "**/*cvv*"
  - "**/*pan*"
`);

  files.set(".ai/guards/human-approval-gate.yaml", `${GENERATED_HEADER}
version: 1
name: human-approval-gate
mode: fail-closed
protected_changes_require:
  - repository-intelligence-gate-ready
  - indexed-impact-analysis
  - detailed-implementation-plan
  - explicit-human-approval
`);

  files.set(".ai/guards/critical-change-guard.yaml", `${GENERATED_HEADER}
version: 1
name: critical-change-guard
critical_domains:
  - identity
  - authorization
  - billing
  - account
  - transaction
  - reporting
  - integration
  - infrastructure
controls:
  - protect pii and regulated data
  - do not run production datafixes autonomously
  - require rollback and validation evidence
`);

  files.set(".ai/workflows/repository-intelligence-workflow.md", `${GENERATED_HEADER}
# Repository Intelligence Workflow

1. Check CodeGraph and CocoIndex executables.
2. Verify local indexes and current commit metadata.
3. Query CodeGraph first.
4. Query CocoIndex second.
5. Open only relevant files and exact sections.
6. Verify critical facts against source.
7. Share a repository intelligence brief with subagents.
`);

  files.set(".ai/templates/repository-intelligence-brief.md", `${GENERATED_HEADER}
# Repository Intelligence Brief

## Gate Status

## Indexed Facts

## Source-Code Verified Facts

## Relevant Modules

## Entry Points And Call Paths

## Data Stores And Contracts

## Related Specs, ADRs, Docs, And Tests

## Impact Areas

## Assumptions And Unknowns
`);

  files.set(".ai/skills-src/repository-intelligence/SKILL.md", `---
name: repository-intelligence
description: Use CodeGraph and CocoIndex before repository brainstorming, planning, impact analysis, review, QA analysis, documentation analysis, or implementation.
---

# Repository Intelligence

Run the local gate first. If CodeGraph or CocoIndex is missing, stale, or failing, stop repository work and troubleshoot setup only.

Use CodeGraph for structure and impact. Use CocoIndex for semantic code/document retrieval. Verify critical behavior against source code.
`);

  files.set(".ai/skills-src/start-task/SKILL.md", `---
name: start-task
description: Convert a request into an indexed engineering task contract before editing.
---

# Start Task

Use the repository-intelligence skill first. Return indexed facts, source-code verified facts, assumptions, risk, smallest safe change, test strategy, and approval needs.
`);

  files.set(".ai/skills-src/implement-feature/SKILL.md", `---
name: implement-feature
description: Implement an explicitly approved scoped change without expanding scope.
---

# Implement Feature

Use repository-intelligence first. Verify approval evidence before protected edits. Refresh CodeGraph and CocoIndex after approved changes.
`);

  files.set(".ai/skills-src/code-review/SKILL.md", `---
name: code-review
description: Review diffs with indexed impact, production risk, and evidence.
---

# Code Review

Use repository-intelligence first. Lead with correctness, security, data integrity, compatibility, concurrency, reliability, performance, observability, and missing tests.
`);

  files.set(".ai/scripts/sync_agent_assets.mjs", `${GENERATED_HEADER}
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const src = path.join(root, ".ai", "skills-src");
const destinations = [path.join(root, ".agents", "skills"), path.join(root, ".claude", "skills")];
const generatedPrefix = "<!-- GENERATED by .ai/scripts/sync_agent_assets.py from ";
const generatedSuffix = ". DO NOT EDIT. -->";
for (const destRoot of destinations) fs.mkdirSync(destRoot, { recursive: true });
for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue;
  const sourceFile = path.join(src, entry.name, "SKILL.md");
  if (!fs.existsSync(sourceFile)) continue;
  const text = fs.readFileSync(sourceFile, "utf8");
  const sourceRel = path.relative(root, sourceFile).replaceAll("\\\\", "/");
  for (const destRoot of destinations) {
    const destDir = path.join(destRoot, entry.name);
    fs.mkdirSync(destDir, { recursive: true });
    fs.writeFileSync(path.join(destDir, "SKILL.md"), generatedPrefix + sourceRel + generatedSuffix + "\\n\\n" + text);
  }
}
console.log("agent skills synchronized");
`);

  files.set(".ai/scripts/validate_agent_config.mjs", `${GENERATED_HEADER}
import fs from "node:fs";
  const required = [
  "AGENTS.md",
  "CLAUDE.md",
  ".ai/guards/repository-intelligence-gate.yaml",
  ".ai/guards/human-approval-gate.yaml",
  ".ai/guards/critical-change-guard.yaml",
  ".agents/skills/repository-intelligence/SKILL.md",
  ".claude/skills/repository-intelligence/SKILL.md"
];
const missing = required.filter((file) => !fs.existsSync(file));
if (missing.length) {
  console.error("Missing AI-agent files:", missing.join(", "));
  process.exit(1);
}
console.log("AI-agent configuration validation passed");
`);

  if (includeClaude) {
    files.set(".claude/settings.json", `${GENERATED_HEADER}
{
  "includeGitInstructions": true,
  "permissions": {
    "deny": [
      "Read(.env)",
      "Read(.env.*)",
      "Read(**/secrets/**)",
      "Read(**/*.pem)"
    ]
  }
}
`);
    files.set(".claude/commands/start-task.md", `${GENERATED_HEADER}
Use \`repository-intelligence\` first, then \`start-task\`. Do not edit files before an approved plan when protected existing-system behavior is involved.
`);
  }

  if (includeCodex) {
    files.set(".agents/README.md", `${GENERATED_HEADER}
# Codex Skills

Generated from \`.ai/skills-src\`. Do not edit generated skills directly.
`);
  }

  return files;
}

export function renderProjectYaml({ detection }) {
  const versions = Object.entries(detection.versions ?? {});
  const manifests = detection.manifests ?? [];
  return `${GENERATED_HEADER}
profile: ${detection.profile}
technologies:
${Object.entries(detection.technologies)
  .map(([name, enabled]) => `  ${name}: ${enabled}`)
  .join("\n")}
${versions.length > 0
    ? `versions:\n${versions.map(([name, version]) => `  ${name}: ${JSON.stringify(version)}`).join("\n")}`
    : "versions: {}"}
${manifests.length > 0
    ? `manifests:\n${manifests.map((relPath) => `  - ${JSON.stringify(relPath)}`).join("\n")}`
    : "manifests: []"}
`;
}

export function renderMergeRequestTemplate({ packageVersion, detection, result }) {
  return `# chore(ai): add AI agent operating system

MR: Pending - developer will create manually.

## Summary

Adds local Claude/Codex AI-agent setup generated by @hunpeolabs/ai-agent-kit.

## Package Version

${packageVersion}

## Detected Profile

${detection.profile}

## Files Created And Updated

- Created: ${result.filesCreated.join(", ") || "None"}
- Updated: ${result.filesUpdated.join(", ") || "None"}
- Preserved: ${result.filesPreserved.join(", ") || "None"}
- Conflicts: ${result.conflicts.join(", ") || "None"}

## Repository Intelligence

- CodeGraph: ${result.toolStatus.codegraph}
- CocoIndex: ${result.toolStatus.cocoindex}

## Validation Evidence

${result.validationResults.join("\n") || "Validation pending."}

## Security Controls

Bootstrap was local only. No files were staged, no branch was created, no commit was created, no push occurred, and no merge request was created.

## Rollback

Use backups under ${result.backupLocation || ".ai-agent-kit/backups/<transaction>"} or revert the local generated files after review.

## Known Limitations

CodeGraph/CocoIndex installation or indexing may require local developer tooling.
`;
}

